+  // and share no common prefix or suffix, so the edit distance is at least 2.
+  const middleSnake = (aLo, aHi, bLo, bHi) => {
+    const n = aHi - aLo;
+    const m = bHi - bLo;
+    const delta = n - m;
+    const odd = (delta & 1) !== 0;
+    const limit = Math.ceil((n + m) / 2);
