+function unifiedHunks(a, b, { context = 3 } = {}) {
+  if (!Number.isInteger(context) || context < 0) {
+    throw new RangeError('context must be a nonnegative integer');
+  }
+  const script = diffLines(a, b);
+  const len = script.length;
+  // oldPos[t] / newPos[t]: lines of a / b consumed before script entry t.
+  const oldPos = new Int32Array(len + 1);
+  const newPos = new Int32Array(len + 1);
+  for (let t = 0; t < len; t++) {
+    const op = script[t].op;
+    oldPos[t + 1] = oldPos[t] + (op === 'insert' ? 0 : 1);
+    newPos[t + 1] = newPos[t] + (op === 'delete' ? 0 : 1);
+  }
+
+  const hunks = [];
+  const emit = (start, end) => {
+    const oldLines = oldPos[end] - oldPos[start];
+    const newLines = newPos[end] - newPos[start];
+    const lines = new Array(end - start);
+    for (let t = start; t < end; t++) {
+      const { op, line } = script[t];
+      lines[t - start] = (op === 'equal' ? ' ' : op === 'delete' ? '-' : '+') + line;
+    }
+    hunks.push({
+      oldStart: oldLines === 0 ? oldPos[start] : oldPos[start] + 1,
+      oldLines,
+      newStart: newLines === 0 ? newPos[start] : newPos[start] + 1,
+      newLines,
+      lines,
+    });
+  };
+
+  let hunkStart = -1; // script index where the open hunk begins
+  let changeEnd = -1; // script index just past the open hunk's last change
+  let t = 0;
+  while (t < len) {
+    if (script[t].op === 'equal') {
+      t++;
+      continue;
+    }
+    const regionStart = t;
+    while (t < len && script[t].op !== 'equal') t++;
+    if (hunkStart >= 0 && regionStart - changeEnd > 2 * context) {
+      emit(hunkStart, changeEnd + context);
+      hunkStart = -1;
+    }
+    if (hunkStart < 0) hunkStart = Math.max(0, regionStart - context);
+    changeEnd = t;
+  }
+  if (hunkStart >= 0) emit(hunkStart, Math.min(len, changeEnd + context));
+  return hunks;
+}
