+function diffLines(a, b) {
+  if (!Array.isArray(a) || !Array.isArray(b)) {
+    throw new TypeError('diffLines expects two arrays of strings');
+  }
+  const ops = editOps(a, b);
+  // Normalize each maximal change region so its deletes precede its inserts.
+  // Within a region the deleted lines of a and inserted lines of b are each
+  // contiguous, so emitting them as two runs keeps both reconstructions intact.
+  const script = [];
+  let i = 0;
+  let j = 0;
+  let delStart = 0;
+  let insStart = 0;
+  const flush = () => {
+    for (let p = delStart; p < i; p++) script.push({ op: 'delete', line: a[p] });
+    for (let q = insStart; q < j; q++) script.push({ op: 'insert', line: b[q] });
+  };
+  for (let t = 0; t < ops.length; t++) {
+    const op = ops[t];
+    if (op === EQUAL) {
+      flush();
+      script.push({ op: 'equal', line: a[i] });
+      i++;
+      j++;
+      delStart = i;
+      insStart = j;
+    } else if (op === DELETE) {
+      i++;
+    } else {
+      j++;
+    }
+  }
+  flush();
+  return script;
+}
+
+const EQUAL = 0;
+const DELETE = 1;
+const INSERT = 2;
+
+/**
+ * Minimal edit operations (EQUAL/DELETE/INSERT codes) turning a into b, using
+ * Myers' linear-space bisection: O((N + M) * D) time, O(N + M) extra space.
+ */
+function editOps(a, b) {
+  // Intern lines so the inner loops compare small integers, not strings.
+  const ids = new Map();
+  const intern = (lines) => {
+    const out = new Int32Array(lines.length);
+    for (let p = 0; p < lines.length; p++) {
+      let id = ids.get(lines[p]);
+      if (id === undefined) {
+        id = ids.size;
+        ids.set(lines[p], id);
+      }
+      out[p] = id;
+    }
+    return out;
+  };
+  const A = intern(a);
+  const B = intern(b);
+  const ops = [];
+  const maxD = Math.ceil((A.length + B.length) / 2);
+  const off = maxD + 1;
+  const vf = new Int32Array(2 * maxD + 3);
+  const vb = new Int32Array(2 * maxD + 3);
+  // Middle snake output, local to the current subproblem.
+  let sx0 = 0;
+  let sy0 = 0;
+  let sx1 = 0;
+  let sy1 = 0;
