'use strict';
const assert = require('node:assert/strict');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const t = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      t[i][j] = a[i] === b[j] ? t[i + 1][j + 1] + 1 : Math.max(t[i + 1][j], t[i][j + 1]);
  return t[0][0];
}

let seed = 12345;
const rnd = (n) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
const alpha = ['', 'x', 'y', '-z', '+w', ' v', 'x'];
for (let iter = 0; iter < 20000; iter++) {
  const a = Array.from({ length: rnd(12) }, () => alpha[rnd(alpha.length)]);
  const b = Array.from({ length: rnd(12) }, () => alpha[rnd(alpha.length)]);
  const ac = a.slice(), bc = b.slice();
  const s = diffLines(a, b);
  assert.deepEqual(s.filter((e) => e.op !== 'insert').map((e) => e.line), a);
  assert.deepEqual(s.filter((e) => e.op !== 'delete').map((e) => e.line), b);
  const L = lcs(a, b);
  assert.equal(s.filter((e) => e.op !== 'equal').length, a.length + b.length - 2 * L);
  for (let t = 1; t < s.length; t++) assert.ok(!(s[t - 1].op === 'insert' && s[t].op === 'delete'));
  assert.deepEqual(diffLines(a, b), s);
  for (const context of [0, 1, 2, 3]) {
    const hs = unifiedHunks(a, b, { context });
    if (L === a.length && L === b.length) assert.deepEqual(hs, []);
    assert.deepEqual(applyHunks(a, hs), b);
    for (const h of hs) {
      // starts must point at real lines
      const oldBody = h.lines.filter((l) => l[0] !== '+').map((l) => l.slice(1));
      const newBody = h.lines.filter((l) => l[0] !== '-').map((l) => l.slice(1));
      const os = h.oldLines ? h.oldStart - 1 : h.oldStart;
      const ns = h.newLines ? h.newStart - 1 : h.newStart;
      assert.deepEqual(a.slice(os, os + h.oldLines), oldBody);
      assert.deepEqual(b.slice(ns, ns + h.newLines), newBody);
    }
    for (let k = 1; k < hs.length; k++) {
      const p = hs[k - 1];
      const gap = (hs[k].oldLines ? hs[k].oldStart - 1 : hs[k].oldStart) - (p.oldLines ? p.oldStart - 1 : p.oldStart) - p.oldLines;
      assert.ok(gap > 0, 'hunks touch');
    }
  }
  assert.deepEqual(a, ac); assert.deepEqual(b, bc);
}
console.log('fuzz ok');

// coordinates for edge zero-line ranges
assert.deepEqual(unifiedHunks([], ['a']), [{ oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+a'] }]);
assert.deepEqual(unifiedHunks(['a'], []), [{ oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-a'] }]);
assert.deepEqual(unifiedHunks(['a', 'b'], ['a'], { context: 0 }), [{ oldStart: 2, oldLines: 1, newStart: 1, newLines: 0, lines: ['-b'] }]);
// applyHunks errors
const a0 = ['a', 'b', 'c'];
const h0 = unifiedHunks(a0, ['a', 'B', 'c'], { context: 0 });
assert.throws(() => applyHunks(['a', 'x', 'c'], h0), /hunk 0 does not apply/);
assert.throws(() => applyHunks(a0, [h0[0], h0[0]]), /hunk 1 does not apply/);
assert.throws(() => applyHunks(a0, [{ ...h0[0], newStart: 5 }]), /hunk 0 does not apply/);
assert.throws(() => applyHunks(a0, [null]), /hunk 0 does not apply/);
const cp = applyHunks(a0, []); assert.deepEqual(cp, a0); assert.notEqual(cp, a0);

// performance
const big = Array.from({ length: 20000 }, (_, i) => `line ${i % 50}`);
const big2 = big.slice(); big2[100] = 'changed'; big2.splice(9000, 3); big2.splice(15000, 0, 'new', 'lines');
let t0 = process.hrtime.bigint();
const hb = unifiedHunks(big, big2);
assert.deepEqual(applyHunks(big, hb), big2);
console.log('20k small change ms', Number(process.hrtime.bigint() - t0) / 1e6);
t0 = process.hrtime.bigint();
const same = diffLines(big, big.slice());
console.log('20k identical ms', Number(process.hrtime.bigint() - t0) / 1e6, same.length);
const r1 = Array.from({ length: 5000 }, (_, i) => `a${i}`), r2 = Array.from({ length: 5000 }, (_, i) => `b${i}`);
t0 = process.hrtime.bigint();
diffLines(r1, r2);
console.log('5k disjoint ms', Number(process.hrtime.bigint() - t0) / 1e6);
